import numpy as np
def frames(g):
    seen=set(); res=[]
    H,W=len(g),len(g[0])
    for i in range(H):
        for j in range(W):
            c=g[i][j]
            if c and (i,j) not in seen:
                cells=[[x,y] for x in range(H) for y in range(W) if g[x][y]==c]
                for x,y in cells: seen.add((x,y))
                rs=[p[0] for p in cells]; cs=[p[1] for p in cells]
                res.append((c,min(rs),max(rs),min(cs),max(cs)))
    return res
def transform(g):
    g=[r[:] for r in g]; H,W=len(g),len(g[0])
    fr=frames(g)
    # source: frame with pattern inside (nonzero interior cells)
    src=None
    for c,r0,r1,c0,c1 in fr:
        inner=[g[x][y] for x in range(r0+1,r1) for y in range(c0+1,c1)]
        if any(v!=0 for v in inner) and src is None:
            pat=[[g[x][y] for y in range(c0+1,c1)] for x in range(r0+1,r1)]
            src=(c,(r1-r0-1,c1-c0-1))
    for c,r0,r1,c0,c1 in fr:
        h,w=r1-r0-1,c1-c0-1
        if (c,h,w)==src[1] and c!=src[0]:
            for x in range(r0+1,r1):
                for y in range(c0+1,c1):
                    g[x][y]=c if pat[x-r0-1][y-c0-1]!=0 else 0
        elif c!=src[0]:
            for x in range(r0,r1+1):
                for y in range(c0,c1+1):
                    g[x][y]=0
    return g
